1. use std::time::{Duration, Instant};
2. 
3. use ratatui::{
4.     layout::{Alignment, Rect},
5.     style::{Color, Modifier, Style},
6.     terminal::Frame,
7.     text::Span,
8.     widgets::Paragraph,
9. };
10. use unicode_width::UnicodeWidthStr;
11. 
12. use crate::display::{DisplayBandwidth, UIState};
13. 
14. pub fn elapsed_time(last_start_time: Instant, cumulative_time: Duration, paused: bool) -> Duration {
15.     if paused {
16.         cumulative_time
17.     } else {
18.         cumulative_time + last_start_time.elapsed()
19.     }
20. }
21. 
22. fn format_duration(d: Duration) -> String {
23.     let s = d.as_secs();
24.     let days = match s / 86400 {
25.         0 => "".to_string(),
26.         1 => "1 day, ".to_string(),
27.         n => format!("{n} days, "),
28.     };
29.     format!(
30.         "{days}{:02}:{:02}:{:02}",
31.         (s / 3600) % 24,
32.         (s / 60) % 60,
33.         s % 60,
34.     )
35. }
36. 
37. pub struct HeaderDetails<'a> {
38.     pub state: &'a UIState,
39.     pub elapsed_time: Duration,
40.     pub paused: bool,
41. }
42. 
43. impl<'a> HeaderDetails<'a> {
44.     pub fn render(&self, frame: &mut Frame, rect: Rect) {
45.         let bandwidth = self.bandwidth_string();
46.         let color = if self.paused {
47.             Color::Yellow
48.         } else {
49.             Color::Green
50.         };
51. 
52.         // do not render time in tests, otherwise the output becomes non-deterministic
53.         // see: https://github.com/imsnif/bandwhich/issues/303
54.         if cfg!(not(test)) && self.state.cumulative_mode {
55.             let elapsed_time = format_duration(self.elapsed_time);
56.             // only render if there is enough width
57.             if bandwidth.width() + 1 + elapsed_time.width() <= rect.width as usize {
58.                 self.render_elapsed_time(frame, rect, &elapsed_time, color);
59.             }
60.         }
61. 
62.         self.render_bandwidth(frame, rect, &bandwidth, color);
63.     }
64. 
65.     fn render_bandwidth(&self, frame: &mut Frame, rect: Rect, bandwidth: &str, color: Color) {
66.         let bandwidth_text = Span::styled(
67.             bandwidth,
68.             Style::default().fg(color).add_modifier(Modifier::BOLD),
69.         );
70. 
71.         let paragraph = Paragraph::new(bandwidth_text).alignment(Alignment::Left);
72.         frame.render_widget(paragraph, rect);
73.     }
74. 
75.     fn bandwidth_string(&self) -> String {
76.         let intrf = self.state.interface_name.as_deref().unwrap_or("all");
77.         let t = if self.state.cumulative_mode {
78.             "Data"
79.         } else {
80.             "Rate"
81.         };
82.         let unit_family = self.state.unit_family;
83.         let up = DisplayBandwidth {
84.             bandwidth: self.state.total_bytes_uploaded as f64,
85.             unit_family,
86.         };
87.         let down = DisplayBandwidth {
88.             bandwidth: self.state.total_bytes_downloaded as f64,
89.             unit_family,
90.         };
91.         let paused = if self.paused { " [PAUSED]" } else { "" };
92.         format!("IF: {intrf} | Total {t} (Up / Down): {up} / {down}{paused}")
93.     }
94. 
95.     fn render_elapsed_time(&self, frame: &mut Frame, rect: Rect, elapsed_time: &str, color: Color) {
96.         let elapsed_time_text = Span::styled(
97.             elapsed_time,
98.             Style::default().fg(color).add_modifier(Modifier::BOLD),
99.         );
100.         let paragraph = Paragraph::new(elapsed_time_text).alignment(Alignment::Right);
101.         frame.render_widget(paragraph, rect);
102.     }
103. }
104.

