53.             vec![rect]
54.         } else if rect.width < FIRST_WIDTH_BREAKPOINT {
55.             // if the horizontal space is not enough, we drop one element and we split horizontally
56.             self.progressive_split(rect, vec![Direction::Vertical])
57.         } else {
58.             // by default we display two elements splitting vertically
59.             self.progressive_split(rect, vec![Direction::Horizontal])
60.         }
61.     }
62. 
63.     fn build_three_children_layout(&self, rect: Rect) -> Vec<Rect> {
64.         // if there are three elements
65.         if rect.height < FIRST_HEIGHT_BREAKPOINT && rect.width < FIRST_WIDTH_BREAKPOINT {
