1. use std::{collections::HashMap, fmt, net::IpAddr, ops::Index, rc::Rc};
2. 
3. use derivative::Derivative;
4. use itertools::Itertools;
5. use ratatui::{
6.     layout::{Constraint, Rect},
7.     style::{Color, Style},
8.     terminal::Frame,
9.     widgets::{Block, Borders, Row},
10. };
11. use unicode_width::{UnicodeWidthChar, UnicodeWidthStr};
12. 
13. use crate::{
14.     display::{Bandwidth, BandwidthUnitFamily, DisplayBandwidth, UIState},
15.     network::{display_connection_string, display_ip_or_host},
16. };
17. 
18. /// The displayed layout choice of a table.
19. /// Each value in the array is the width of each column.
20. ///
21. /// Note that this only determines how a table is displayed, not what data it contains.
22. ///
23. /// If we intend to display different number of columns in the future,
24. /// then new variants should be added.
25. #[derive(Copy, Clone, Debug)]
26. pub enum DisplayLayout {
27.     /// Show 2 columns.
28.     C2([u16; 2]),
29.     /// Show 3 columns.
30.     C3([u16; 3]),
31.     /// Show 4 columns.
32.     C4([u16; 4]),
33. }
34. 
35. impl Index<usize> for DisplayLayout {
36.     type Output = u16;
37. 
38.     fn index(&self, i: usize) -> &Self::Output {
39.         match self {
40.             Self::C2(arr) => &arr[i],
41.             Self::C3(arr) => &arr[i],
42.             Self::C4(arr) => &arr[i],
43.         }
44.     }
45. }
46. 
47. impl DisplayLayout {
48.     #[inline]
49.     fn columns_count(&self) -> usize {
50.         match self {
51.             Self::C2(_) => 2,
52.             Self::C3(_) => 3,
53.             Self::C4(_) => 4,
54.         }
55.     }
56. 
57.     #[inline]
58.     fn iter(&self) -> impl Iterator<Item = &u16> {
59.         match self {
60.             Self::C2(ws) => ws.iter(),
61.             Self::C3(ws) => ws.iter(),
62.             Self::C4(ws) => ws.iter(),
63.         }
64.     }
65. 
66.     #[inline]
67.     fn widths_sum(&self) -> u16 {
68.         self.iter().sum()
69.     }
70. 
71.     /// Returns the computed actual width and the spacer width.
72.     ///
73.     /// See [`Table`] for layout rules.
74.     fn compute_actual_widths(&self, available: u16) -> (Self, u16) {
75.         let columns_count = self.columns_count() as u16;
76.         let desired_min = self.widths_sum();
77. 
78.         // spacer max width is 2
79.         let spacer = if available > desired_min {
80.             ((available - desired_min) / (columns_count - 1)).min(2)
81.         } else {
82.             0
83.         };
84.         let available_without_spacers = available - spacer * (columns_count - 1);
85. 
86.         // multiplier
87.         let m = available_without_spacers as f64 / desired_min as f64;
88. 
89.         // remainder width is arbitrarily given to column 0
90.         let computed = match *self {
91.             Self::C2([_w0, w1]) => {
92.                 let w1_new = (w1 as f64 * m).trunc() as u16;
93.                 Self::C2([available_without_spacers - w1_new, w1_new])
94.             }
95.             Self::C3([_w0, w1, w2]) => {
96.                 let w1_new = (w1 as f64 * m).trunc() as u16;
97.                 let w2_new = (w2 as f64 * m).trunc() as u16;
98.                 Self::C3([available_without_spacers - w1_new - w2_new, w1_new, w2_new])
99.             }
100.             Self::C4([_w0, w1, w2, w3]) => {
101.                 let w1_new = (w1 as f64 * m).trunc() as u16;
102.                 let w2_new = (w2 as f64 * m).trunc() as u16;
103.                 let w3_new = (w3 as f64 * m).trunc() as u16;
104.                 Self::C4([
105.                     available_without_spacers - w1_new - w2_new - w3_new,
106.                     w1_new,
107.                     w2_new,
108.                     w3_new,
109.                 ])
110.             }
111.         };
112. 
113.         (computed, spacer)
114.     }
115. }
116. 
117. /// All data of a table.
118. ///
119. /// If tables with different number of columns are added in the future,
120. /// then new variants should be added.
121. #[derive(Clone, Debug)]
122. enum TableData {
123.     /// A table with 3 columns.
124.     C3(NColsTableData<3>),
125.     /// A table with 4 columns.
126.     C4(NColsTableData<4>),
127. }
128. 
129. impl From<NColsTableData<3>> for TableData {
130.     fn from(data: NColsTableData<3>) -> Self {
131.         Self::C3(data)
132.     }
133. }
134. 
135. impl From<NColsTableData<4>> for TableData {
136.     fn from(data: NColsTableData<4>) -> Self {
137.         Self::C4(data)
138.     }
139. }
140. 
141. impl TableData {
142.     fn column_names(&self) -> &[&str] {
143.         match self {
144.             Self::C3(inner) => &inner.column_names,
145.             Self::C4(inner) => &inner.column_names,
146.         }
147.     }
148. 
149.     fn rows(&self) -> Vec<&[String]> {
150.         match self {
151.             Self::C3(inner) => inner.rows.iter().map(|r| r.as_slice()).collect(),
152.             Self::C4(inner) => inner.rows.iter().map(|r| r.as_slice()).collect(),
153.         }
154.     }
155. 
156.     fn column_selector(&self) -> &dyn Fn(&DisplayLayout) -> Vec<usize> {
157.         match self {
158.             Self::C3(inner) => inner.column_selector.as_ref(),
159.             Self::C4(inner) => inner.column_selector.as_ref(),
160.         }
161.     }
162. }
163. 
164. /// All data of a table with `C` columns.
165. ///
166. /// Note that the number of columns here is independent of the number of columns
167. /// being actually shown. If width-constrained, we might only show some of the columns.
168. #[derive(Clone, Derivative)]
169. #[derivative(Debug)]
170. struct NColsTableData<const C: usize> {
171.     /// The name of each column.
172.     column_names: [&'static str; C],
173.     /// All rows of data.
174.     rows: Vec<[String; C]>,
175.     /// Function to determine which columns to show for a given layout.
176.     ///
177.     /// This function should return a vector of column indices.
178.     /// The indices should be less than `C`; otherwise this will cause a runtime panic.
179.     #[derivative(Debug(format_with = "debug_fn::<C>"))]
180.     column_selector: Rc<ColumnSelectorFn>,
181. }
182. 
183. /// Clippy wanted me to write this. 💢
184. type ColumnSelectorFn = dyn Fn(&DisplayLayout) -> Vec<usize>;
185. 
186. fn debug_fn<const C: usize>(
187.     _func: &Rc<ColumnSelectorFn>,
188.     f: &mut fmt::Formatter,
189. ) -> Result<(), fmt::Error> {
190.     write!(f, "Rc</* function pointer */>")
191. }
192. 
193. /// A table displayed by bandwhich.
194. #[derive(Clone, Debug)]
195. pub struct Table {
196.     title: &'static str,
197.     /// A layout mapping between minimum available width and the width of each column.
198.     ///
199.     /// Note that the width of each column here is the "desired minimum width".
200.     ///
201.     /// - Wt = available width of table
202.     /// - Wd = sum of desired minimum width of each column
